<?php
declare(strict_types=1);
return new class implements ToolCallingProviderAdapter {
 private function call(array $p,string $path,array $payload=[]):array{$url=rtrim($p['base_url'],'/').$path;$ch=curl_init($url);$headers=['Accept: application/json'];if(($p['api_key']??'')!=='')$headers[]='Authorization: Bearer '.$p['api_key'];if($payload){$headers[]='Content-Type: application/json';curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($payload,JSON_UNESCAPED_UNICODE));}curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>$headers,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>120,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);$raw=curl_exec($ch);$err=curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if($raw===false)throw new RuntimeException('Provider connection failed: '.$err);try{$d=json_decode($raw,true,64,JSON_THROW_ON_ERROR);}catch(JsonException $e){throw new RuntimeException('Provider returned invalid JSON.',0,$e);}if(!is_array($d))throw new RuntimeException('Provider returned an invalid response object.');if($code<200||$code>=300)throw new RuntimeException('Provider HTTP '.$code.': '.substr((string)($d['error']['message']??$raw),0,500));return $d;}
 public function models(array $p):array{$d=$this->call($p,'/models');return array_map(fn($m)=>['id'=>$m['id'],'name'=>$m['id']],$d['data']??[]);}
 public function chat(array $p,string $model,array $messages):string{$payload=['model'=>$model,'messages'=>$messages,'stream'=>false];if(preg_match('/qwen3/i',$model)===1)$payload['chat_template_kwargs']=['enable_thinking'=>false];$d=$this->call($p,'/chat/completions',$payload);return (string)($d['choices'][0]['message']['content']??'');}
 public function chatWithTools(array $p,string $model,array $messages,array $tools):ProviderToolCallResult{if(!array_is_list($tools)||count($tools)<1||count($tools)>64)throw new InvalidArgumentException('Provider tool definitions must contain between 1 and 64 entries.');foreach($tools as $tool)if(!is_array($tool)||($tool['type']??'')!=='function'||!is_array($tool['function']??null)||!preg_match('/^[A-Za-z0-9_.-]{1,128}$/',(string)($tool['function']['name']??''))||!is_array($tool['function']['parameters']??null)||($tool['function']['parameters']['type']??'')!=='object')throw new InvalidArgumentException('Provider tool definition is invalid.');$payload=['model'=>$model,'messages'=>$messages,'stream'=>false,'tools'=>$tools,'tool_choice'=>'auto','parallel_tool_calls'=>false];if(preg_match('/qwen3/i',$model)===1)$payload['chat_template_kwargs']=['enable_thinking'=>false];return ProviderToolCallResult::fromOpenAIResponse($this->call($p,'/chat/completions',$payload));}
};
